import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_DIR = path.join(__dirname, 'data');

export async function listTools() {
  return [
    {
      name: 'file_metadata',
      description:
        'Return metadata (relative path, byte size, lowercase extension) for a file under the workspace data directory. Does not expose file contents.',
      inputSchema: {
        type: 'object',
        properties: {
          path: {
            type: 'string',
            description: 'Relative path of the file within the data directory.',
          },
        },
        required: ['path'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'file_metadata') {
    throw new Error('Unknown tool: ' + name);
  }

  const { path: rel } = args;
  if (typeof rel !== 'string' || rel === '') {
    throw new Error('path is required');
  }
  if (path.isAbsolute(rel)) {
    throw new Error('path must be relative to the data directory');
  }

  // Reject any traversal attempt: a literal '..' segment is not allowed,
  // even if normalization would resolve it back inside the data directory.
  if (rel.split(/[\\/]/).includes('..')) {
    throw new Error('path must stay within the data directory');
  }

  const normalized = path.normalize(rel);

  const resolvedData = path.resolve(DATA_DIR);
  const resolvedFull = path.resolve(DATA_DIR, normalized);
  if (resolvedFull !== resolvedData && !resolvedFull.startsWith(resolvedData + path.sep)) {
    throw new Error('path must stay within the data directory');
  }

  let stat;
  try {
    stat = fs.statSync(resolvedFull);
  } catch (e) {
    throw new Error('File not found: ' + rel);
  }
  if (!stat.isFile()) {
    throw new Error('Not a file: ' + rel);
  }

  const relPath = path.relative(resolvedData, resolvedFull);
  const ext = path.extname(relPath).toLowerCase();
  const text = `path: ${relPath}\nsize: ${stat.size}\nextension: ${ext}`;

  return {
    content: [{ type: 'text', text }],
  };
}

